import { IBackOffOptions } from "exponential-backoff/src/options";
import { fullJitter } from "exponential-backoff/src/jitter/full/full.jitter";
import { noJitter } from "exponential-backoff/src/jitter/no/no.jitter";

export type Jitter = (delay: number) => number;

export function JitterFactory(options: IBackOffOptions): Jitter {
  switch (options.jitter) {
    case "full":
      return fullJitter;

    case "none":
    default:
      return noJitter;
  }
}
